package com.notesshared.servlet;
import com.notesshared.dao.MaterialDao;import com.notesshared.model.Material;import com.notesshared.util.UploadUtil;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.nio.file.*;
@WebServlet("/materials/download") public class DownloadServlet extends HttpServlet{private final MaterialDao materials=new MaterialDao();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession h=r.getSession(false);if(h==null||h.getAttribute("userId")==null){s.sendError(401);return;}try{int cid=(int)h.getAttribute("collegeId"),mid=Integer.parseInt(r.getParameter("id"));Material m=materials.findVisibleById(mid,cid);if(m==null){s.sendError(404);return;}Path base=UploadUtil.uploadDirectory(),file=base.resolve(m.getStoredFilename()).normalize();if(!file.startsWith(base)||!Files.exists(file)){s.sendError(404);return;}s.setContentType(m.getContentType());s.setHeader("Content-Disposition","inline; filename=\""+m.getOriginalFilename().replace("\"","'")+"\"");s.setContentLengthLong(Files.size(file));Files.copy(file,s.getOutputStream());}catch(NumberFormatException e){s.sendError(400);}catch(Exception e){s.sendError(500);}}}
